import{_ as t,H as a,f as o,i}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"03 | Bottlerocket：为云原生而生的强大操作系统","description":"","frontmatter":{},"headers":[{"level":2,"title":"运维之痛：给操作系统打补丁","slug":"运维之痛-给操作系统打补丁","link":"#运维之痛-给操作系统打补丁","children":[]},{"level":2,"title":"什么是不可变基础设施？","slug":"什么是不可变基础设施","link":"#什么是不可变基础设施","children":[]},{"level":2,"title":"CoreOS/Atomic - 出师未捷","slug":"coreos-atomic-出师未捷","link":"#coreos-atomic-出师未捷","children":[]},{"level":2,"title":"Bottlerocket - 旗开得胜","slug":"bottlerocket-旗开得胜","link":"#bottlerocket-旗开得胜","children":[]},{"level":2,"title":"快速体验","slug":"快速体验","link":"#快速体验","children":[{"level":3,"title":"调试实操环节","slug":"调试实操环节","link":"#调试实操环节","children":[]}]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"云原生基础架构实战课/03｜Bottlerocket：为云原生而生的强大操作系统.md","filePath":"云原生基础架构实战课/03｜Bottlerocket：为云原生而生的强大操作系统.md","lastUpdated":1795537597000}'),l={name:"云原生基础架构实战课/03｜Bottlerocket：为云原生而生的强大操作系统.md"};function n(p,e,s,r,c,E){return a(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="_03-bottlerocket-为云原生而生的强大操作系统" tabindex="-1">03 | Bottlerocket：为云原生而生的强大操作系统 <a class="header-anchor" href="#_03-bottlerocket-为云原生而生的强大操作系统" aria-label="Permalink to &quot;03 | Bottlerocket：为云原生而生的强大操作系统&quot;">​</a></h1><p>你好，我是潘野。</p><p>在做云原生训练营助教的时候，很多同学对“不可变基础设施”这一个概念不太理解，如果你在网络上搜索“不可变基础设施”，往往会到得这样的说法：</p><ul><li>不可变基础设施是指一种基于代码和配置的基础设施管理方法，其中所有的更改和配置都是通过重新构建和替换来实现的，而不是直接修改现有的设施。这种方法的目标是确保系统的稳定性和一致性，减少人为错误和配置漂移，并提高系统的可靠性和可管理性。</li></ul><p>很多同学读了之后一头雾水，产生了后面这些疑问。</p><ul><li><p>我用 puppet 或者 ansible 不也是代码方式来管理基础设施，这样不是也能保证一致性吗？</p></li><li><p>如果更改配置都是通过替换实例的方式，这样做的成本是不是太高了？</p></li><li><p>没看出“不可变”的好处在哪里？</p></li></ul><p>今天这节课，我就带你重新理解一下“不可变基础设施”，看看它究竟带来了什么样的管理优势。最后，我还会带你一起体验下，不可变基础设施中的新星 bottlerocket 如何使用。</p><h2 id="运维之痛-给操作系统打补丁" tabindex="-1">运维之痛：给操作系统打补丁 <a class="header-anchor" href="#运维之痛-给操作系统打补丁" aria-label="Permalink to &quot;运维之痛：给操作系统打补丁&quot;">​</a></h2><p>通过前面的学习，我们知道了在虚拟机时代，的确可以通过 Puppet、Saltstack、Ansible 这类配置管理工具来实现 IaC。即便到今天，这些工具也仍然在运维管理工作中非常流行。</p><p>以往比较常见的运维工作就是给虚拟机打安全补丁，或者是升级主机内核，这时我们的做法基本都是更改 Puppet 的配置文件，配置推送到目标机器，并且联系业务团队安排时间做主机重启。用这种方式管理的机器，我们叫做可变基础架构。</p><p>如果公司里机器数量是几百、几千台，通过自己开发的运维平台，投入三四个人力，花上半个月基本也可以搞定。但是如果你公司里的机器数量在十万台以上，你会发现必须安排几个运维同学，常年给操作系统打补丁。</p><p>在虚拟机时代，一个机器上一般只跑一个应用，为了提高资源利用率，最多也就跑三四个应用，那么通知用户、给机器打补丁，这些事可能还属于可控范围内。然而现在的容器环境中，一个主机上动辄几十到上百个容器，并且掺杂了很多不同的应用。这时候工作变得不太可控，三四个人可能半年也做不完一轮维护。</p><p>近些年安全管理在各个公司里都逐渐上升到公司战略层面，安全管理中最常见的一个事情就是给操作系统打安全补丁；而且自从 Docker 出现之后，Linux 操作系统的内核版本演进变得快了很多，新的内核中包含了很多为容器设计的特性，比如最近非常热门的 eBPF，它要求Kernel 的版本不能低于 4.1，而真正比较完善的是 4.18 这个版本，所以 Kernel 版本的跟进也成为了基础架构管理中的一个强需求。</p><p>那么在云原生时代，如果我们还是依靠原来的管理方式，通过 Puppet 等配置管理工具滚动地升级内核版本、重启主机，这不仅非常耗费人力，而且还可能会造成一些应用的中断，并不是一个很优雅的管理方式。</p><p>既然云原生时代，容器这种部署稳定可靠且易管理的方式已经深入人心，我们能不能像管理容器一样来管理虚拟机，来简化运维操作呢？</p><h2 id="什么是不可变基础设施" tabindex="-1">什么是不可变基础设施？ <a class="header-anchor" href="#什么是不可变基础设施" aria-label="Permalink to &quot;什么是不可变基础设施？&quot;">​</a></h2><p>想要像管理容器一样管理虚拟机，我们需要先分析一下容器有哪些特点。</p><p>我们第一反应大概会包括这几个特点：能快速启动、轻量级、有版本控制等等。</p><p>所以对应到虚拟机上，我们就会有这样的期望。</p><ul><li><p>虚拟机启动要越快越好，所以镜像要最小化。</p></li><li><p>虚拟机镜像是有版本控制的，当虚拟机需要打补丁的时候，我们需要做的是，打包编译新的镜像，然后用新镜像启动机器做直接替换。</p></li><li><p>利用 Kubernetes 自身的能力，保证 pod 平滑地漂移到新的节点上即可。一切的管理都由Kubernetes 来负责，不再需要人工介入管理。</p></li></ul><p>我们期望的这种管理方式其实就是不可变基础设施！</p><p>有了感性认知以后，我们就可以重新拆解不可变基础设施的定义了，这里有三个关键点需要掌握。</p><p>关键点一，一种基于代码和配置的基础设施管理方法。</p><p>我们打包一个容器镜像的过程是，写 Dockerfile，编译镜像，推送进容器仓库。一般这个过程都是由公司内的 CI/CD 工具来完成。其实虚拟机的镜像管理也是类似的做法，利用 Packer 这样的打包工具，配合 CI 工具来生成虚拟机镜像，然后推送到虚拟机镜像管理的仓库。</p><p>关键点二，所有的更改和配置都是通过重新构建和替换来实现的。</p><p>当 v1 版本的虚拟机需要更新到 v2 版本的虚拟机，我们只要先启动 v2 版本的虚拟机，然后将v1 版本虚拟机中的 workload 转移到新机器即可。我估计，熟悉 Kubernetes 的同学立刻就可以想到有哪些方法可以转移 workload。</p><p>关键点三，确保系统的稳定性和一致性，减少人为错误和配置漂移。</p><p>运维的同学应该深有体会，面对几万台机器的管理，人为推错了配置这种情况并不少。另外，不健壮的配置脚本也可能引起环境配置不一致。而实施不可变基础设施的最大作用，就是避免这类情况出现。</p><p>好，前面我们花了不少篇幅讲解不可变基础设施的概念，为了让你加深对它的认识，我们来看看历史上曾经出现的不可变基础设施的技术。</p><h2 id="coreos-atomic-出师未捷" tabindex="-1">CoreOS/Atomic - 出师未捷 <a class="header-anchor" href="#coreos-atomic-出师未捷" aria-label="Permalink to &quot;CoreOS/Atomic - 出师未捷&quot;">​</a></h2><p>我们都知道 Kubernetes 的核心组件是 etcd。最早发布 etcd 的这家公司叫 CoreOS，公司的名字就是自家的一个操作系统 CoreOS。CoreOS 为容器专门设计操作系统的鼻祖，可能你没用过甚至没听说过它，所以我简单做个介绍。</p><p>CoreOS 是在 2013 年出现的，CoreOS 比 Kubernetes 还早出来一年，CoreOS 就是为“不可变基础设施”量身打造的操作系统，它与传统的 CentOS/Ubuntu 这类系统不同，具有以下特点。</p><ul><li><p>CoreOS 利用主动和被动双分区方案来更新 OS，使用分区作为一个单元，而不是一个包一个包的更新。这使得每次更新变得快速、可靠，而且很容易回滚。</p></li><li><p>CoreOS 内置了服务发现工具 etcd，容器管理工具 rkt。</p></li><li><p>CoreOS 专门为云环境设定，提供了 AWS、GCP、Azure 等各大云厂商镜像。</p></li></ul><p>作为 Linux 操作系统的扛把子 Redhat，看到 CoreOS 的设计方式之后大为震惊，基于 RHEL的系统也推出了专为容器设计的操作系统 Atomic，eBay 的容器平台使用的就是 Atomic。</p><p>2018 年的时候，云原生热潮席卷全球，Red Hat 干脆直接收购了 CoreOS，并且将 CoreOS与 Red Hat 原有的 Atomic 操作系统项目合并，一并改名叫 Fedora CoreOS。</p><p>这两个操作系统的特点，非常符合前面所说的不可变基础设施的最佳实践，但是两个项目最终合并成为了商业产品。那么在容器时代，还有没有其他可以不花钱的替代产品了？</p><p>有，这就是 Amazon 专门推出的、为容器服务的操作系统 Bottlerocket！</p><h2 id="bottlerocket-旗开得胜" tabindex="-1">Bottlerocket - 旗开得胜 <a class="header-anchor" href="#bottlerocket-旗开得胜" aria-label="Permalink to &quot;Bottlerocket - 旗开得胜&quot;">​</a></h2><p>Bottlerocket 是 Amazon 在 2020 年 3 月时发布的一套完全开源的操作系统，由现有开源组件（例如 Linux 内核）、约 50 个软件包以及专为 Bottlerocket 编写的新组件（主要以 Rust 及 Go语言编写而成）共同组成。你可以在 AWS 网站上找到它们的介绍。</p><p>你可能仍然有顾虑，前面提到 CoreOS 被收购了，Atomic 项目就终止了，那么 Bottlerocket有没有这样的风险呢？</p><p>从现在的情况来看，Bottlerocket 中 Amazon 自己编写的组件使用 Apache 2.0 许可或 MIT 许可，Linux Kernel 等其他开源组件遵守原始开源许可，所以风险不大。同时 Bottlerocket 项目源自长期以来在 Amazon 大规模生产运行服务当中总结出的经验教训，结合了过去多年以来Amazon 对于容器技术的提炼与沉淀，可以说 Bottlerocket 是现在容器操作系统的绝佳选择。</p><p>Bottlerocket 和传统操作系统相比，引入了一些新的概念，这里我着重讲一下 Bottlerocket 的三大特点。</p><p>第一，Bottlerocket 没有软件包管理器，一切应用程序用容器运行。</p><p>很多同学不太理解什么是“没有包管理器”。传统的操作系统，比如 Ubuntu 或者 centOS，它们的包管理器是 RPM 和 DEB，基于 RHEL 系统的 Atomic 就是用的 RPM 包管理的模式。然而，在 Bottlerocket 没有任何的包管理工具，Bottlerocket 系统里的组件是直接以二进制形式打包进镜像的。这样做可以减少很多无用组件，达到操作系统最小化的目的。</p><p>第二，Bottlerocket 是一个 API 驱动的操作系统。</p><p>“API 驱动”，这听起来也比较难理解。简单来说就是当操作系统启动之后，系统没有 ssh，也没有传统 Linux 上必备的 shell。如果我们想调试系统，需要启动一个带有 shell 的容器来调试、手动更新和更改主机上的配置。那么启动这个 shell 的容器，就是调用 Bottlerocket 的API 来启动这个 shell，在后面的章节我会演示如何使用它的 API，这里你先有个印象就好。</p><p>第三，Bottlerocket 根文件系统是只读，不可修改，这是实现“不可变基础设施”的一个重要特性。而非根分区系统也就是用户存数据的分区，可以读写，采用 SELinux 策略来保护非根文件系统中的文件。</p><h2 id="快速体验" tabindex="-1">快速体验 <a class="header-anchor" href="#快速体验" aria-label="Permalink to &quot;快速体验&quot;">​</a></h2><p>说了这么多 Bottlerocket 的特点，我们怎么快速上手呢？</p><p>我猜有同学已经通过搜索点开了 Bottlerocket 的 GitHub 链接，但是可能会发现 GitHub 里一些指引看不明白，比如说，当我们接触一个新的操作系统，第一步肯定是在虚拟机里尝试安装，但是你在 Bottlerocket 的 GitHub 上找不到“如何安装 Bottlerocket”这样的文档。</p><p>这是因为 Bottlerocket 是为容器而生，所以整个的设计是围绕 Kubernetes 的，所以它的使用离不开 kubernetes 集群。如果想体验 Bottlerocket，最快捷的办法是在 AWS 上启动一个 EKS集群，然后选择 Bottlerocket 作为节点的操作系统。</p><p>当然，如果你要想把它用在物理机器或者在本地环境里跑起来，Bottlerocket 也可以提供了相应的文档指引，你可以自行查阅 Github 上的这个链接了解更多内容。在 Bottlerocket 的Github 上，Bottlerocket 不但为 Kubernetes 1.23 之后的每个主版本都提供了镜像，同时还提供了 AWS AMI 镜像和 VMware 的镜像。</p><h3 id="调试实操环节" tabindex="-1">调试实操环节 <a class="header-anchor" href="#调试实操环节" aria-label="Permalink to &quot;调试实操环节&quot;">​</a></h3><p>最后，我们来简单体验一下怎么进入 Bottlerocket 的调试模式，并且尝试一些重启机器之类的操作，找找手感。</p><p>首先，我们在 EKS 集群里添加一个节点组，其中 AMI 的类型是 Bottlerocket_x86_64，你可以参考后面的截图来配置。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E5%9F%BA%E7%A1%80%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/03/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E5%9F%BA%E7%A1%80%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/03/1.png" alt=""></a></p><p>添加完成之后等待片刻，我们就可以在集群里看到一个新的节点产生。之后用 -owide 参数就可以看到这个节点的操作系统是 Bottlerocket。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~&gt;kubectl get node ip-192-168-81-115.ap-east-1.compute.internal -owide</span></span>
<span class="line"><span>NAME                                           STATUS   ROLES    AGE     VERSION</span></span>
<span class="line"><span>ip-192-168-81-115.ap-east-1.compute.internal   Ready    &lt;​none&gt;   3m47s   v1.27.7-</span></span></code></pre></div><p>接下来，让我们在 AWS 的 console 上找到这个 EC2 节点，使用 session manager 这个工具连接这个节点。然后你会看到 Bottlerocket 的欢迎提示，同时给你提示了三个命令。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第一个命令是  apiclient ，这是用来与 Bottlerocket API 交互的工具。</span></span>
<span class="line"><span>第二个命令是 enter-admin-container  ，它的作用是启动一个具有 admin 权限的容器，</span></span></code></pre></div><p>我们接下来的操作都会在 admin 容器中进行。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第三个命令是  disable-admin-container ，该命令用来关闭具备 admin 权限的容器。</span></span></code></pre></div><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E5%9F%BA%E7%A1%80%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/03/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E5%9F%BA%E7%A1%80%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/03/2.png" alt=""></a></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>敲下 enter-admin-container 命令之后，我们即可进入 admin 容器。然后敲下 apiclient</span></span></code></pre></div><p>reboot 命令，此时你会发现提示机器重启了，集群中这个节点变成了 NotReady 的状态。等机器启动完成之后，这个节点会重新变成 Ready 状态。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E5%9F%BA%E7%A1%80%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/03/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E5%9F%BA%E7%A1%80%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/03/3.png" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E5%9F%BA%E7%A1%80%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/03/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E5%9F%BA%E7%A1%80%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/03/4.png" alt=""></a></p><p>短短几分钟我们就体验了 Bottlerocket 的启动，API 交互的方法。如果你有兴趣，可以进入admin 容器，运行 apiclient -h 来仔细研究一下 apiclient 这个命令能做哪些事情。下面这张图展示了该命令支持的参数，供你参考。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E5%9F%BA%E7%A1%80%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/03/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E4%BA%91%E5%8E%9F%E7%94%9F%E5%9F%BA%E7%A1%80%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/03/5.png" alt=""></a></p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>不可变基础设施是云原生时代一种构建和管理基础设施的方法，这种方法提供了可靠性、可伸缩性和可重复性。而 Bottlerocket 是一个轻量级，高度可靠性和安全性的 Linux 发行版，是对不可变基础设施的最佳实践。</p><p>今天，我们学习了不可变基础设施的概念，其中不可变基础设施概念的三个关键点你需要重点掌握。之后，我们还通过实操体会到 Bottlerocket 的一些用法，还有其他的一些特点，同学们可以课后自行查阅 Bottlerocket 的官方文档。建议你课后对照课程讲解，动手多多练习，加深记忆。</p><p>后面的课程中，我们启动的集群会默认使用 Bottlerocket 作为 kubernetes nodes，相信随着课程学习的深入，你也会对 Bottlerocket 更加熟悉。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>这一讲，我提到容器环境中重启主机这有可能会造成一些应用的中断。你知道什么样的情况会造成应用中断么？我们又该如何预防？</p><p>欢迎你和我在评论区一起讨论。如果这一讲对你有帮助，别忘了分享给身边更多同事、朋友。</p>`,76)])])}const d=t(l,[["render",n]]);export{u as __pageData,d as default};
